gKG(){return"\u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930 \u0915\u0930\u0915\u0947 \u0906\u092a \u092a\u0941\u0937\u094d\u091f\u093f \u0915\u0930\u0924\u0947 \u0939\u0948\u0902 \u0915\u093f \u0906\u092a \u0938\u0947\u0935\u093e \u092a\u094d\u0930\u0926\u093e\u0924\u093e \u0915\u0940 \u0915\u0940\u092e\u0924, \u0938\u092e\u092f \u0914\u0930 \u0936\u0930\u094d\u0924\u0947\u0902 \u0938\u094d\u0935\u0940\u0915\u093e\u0930 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902 \u0924\u0925\u093e \u0917\u094d\u0930\u093e\u0939\u0915 \u0915\u0947 \u0930\u0942\u092a \u092e\u0947\u0902 \u0905\u092a\u0928\u0947 \u0926\u093e\u092f\u093f\u0924\u094d\u0935 \u092a\u0942\u0930\u0947 \u0915\u0930\u0947\u0902\u0917\u0947\u0964 \u0911\u0930\u094d\u0921\u0930 \u0915\u0947 \u0915\u093e\u092e \u092e\u0947\u0902 \u091c\u093e\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0938\u0947\u0935\u093e \u092a\u094d\u0930\u0926\u093e\u0924\u093e \u0915\u094b \u0905\u0932\u0917 \u0938\u0947 \u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930 \u0915\u0930\u0915\u0947 \u0938\u0939\u092e\u0924\u093f \u0926\u0947\u0928\u0940 \u0939\u094b\u0917\u0940\u0964"},
gKO(){return"\u0906\u092a \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 \u0930\u0942\u092a \u0938\u0947 \u0935\u093f\u0936\u0947\u0937\u091c\u094d\u091e \u091a\u0941\u0928\u0924\u0947 \u0939\u0948\u0902 \u0914\u0930 \u0938\u0940\u0927\u0947 \u0909\u0938\u0915\u0947 \u0938\u093e\u0925 \u0905\u0928\u0941\u092c\u0902\u0927 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902\u0964 \u0915\u093e\u0928\u0942\u0928 \u0926\u094d\u0935\u093e\u0930\u093e \u0905\u0928\u0941\u092e\u0924 \u0938\u0940\u092e\u093e \u0924\u0915, ClearFix \u091a\u0941\u0928\u0947 \u0917\u090f \u0935\u093f\u0936\u0947\u0937\u091c\u094d\u091e \u0915\u0947 \u0915\u093e\u0930\u094d\u092f\u094b\u0902 \u092f\u093e \u091a\u0942\u0915\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u0909\u0924\u094d\u0924\u0930\u0926\u093e\u092f\u0940 \u0928\u0939\u0940\u0902 \u0939\u0948 \u0914\u0930 \u0909\u0938\u0915\u0940 \u092f\u094b\u0917\u094d\u092f\u0924\u093e \u092f\u093e \u0908\u092e\u093e\u0928\u0926\u093e\u0930\u0940 \u0915\u0940 \u0917\u093e\u0930\u0902\u091f\u0940 \u0928\u0939\u0940\u0902 \u0926\u0947\u0924\u093e\u0964"},
gKN(){return"\u092e\u0948\u0902\u0928\u0947 \u0935\u093f\u0936\u0947\u0937\u091c\u094d\u091e \u091a\u0941\u0928\u0928\u0947 \u0914\u0930 ClearFix \u0915\u0940 \u091c\u093f\u092e\u094d\u092e\u0947\u0926\u093e\u0930\u0940 \u0915\u0940 \u0938\u0940\u092e\u093e\u0913\u0902 \u0915\u0947 \u092c\u093e\u0930\u0947 \u092e\u0947\u0902 \u0938\u0942\u091a\u0928\u093e \u092a\u0922\u093c \u0932\u0940 \u0939\u0948\u0964"},
gKI(){return"\u092e\u0948\u0902\u0928\u0947 \u0907\u0928 \u0936\u0930\u094d\u0924\u094b\u0902 \u0915\u094b \u092a\u0922\u093c \u0932\u093f\u092f\u093e \u0939\u0948 \u0914\u0930 \u0917\u094d\u0930\u093e\u0939\u0915 \u0915\u0947 \u0930\u0942\u092a \u092e\u0947\u0902 \u0907\u0938 \u0938\u092e\u091d\u094c\u0924\u0947 \u0915\u0947 \u0905\u092a\u0928\u0947 \u0939\u093f\u0938\u094d\u0938\u0947 \u0915\u094b \u092a\u0942\u0930\u0940 \u0924\u0930\u0939 \u0928\u093f\u092d\u093e\u0928\u0947 \u0915\u0940 \u092a\u094d\u0930\u0924\u093f\u092c\u0926\u094d\u0927\u0924\u093e \u0915\u0930\u0924\u093e/\u0915\u0930\u0924\u0940 \u0939\u0942\u0901\u0964"},
gKF(){return"\u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930 \u0915\u0930\u0915\u0947 \u0938\u0947\u0935\u093e \u092a\u094d\u0930\u0926\u093e\u0924\u093e \u0915\u094b \u092d\u0947\u091c\u0947\u0902"},
gKy(){return"\u0907\u0938 \u0938\u092e\u091d\u094c\u0924\u0947 \u0915\u0947 \u0905\u0902\u0924\u0930\u094d\u0917\u0924 \u0911\u0930\u094d\u0921\u0930"},
gKD(){return"\u0917\u094d\u0930\u093e\u0939\u0915 \u0914\u0930 \u0938\u0947\u0935\u093e \u092a\u094d\u0930\u0926\u093e\u0924\u093e \u0915\u0947 \u092c\u0940\u091a \u0938\u092e\u091d\u094c\u0924\u093e"},
gKx(){return"\u0917\u094d\u0930\u093e\u0939\u0915"},
gKz(){return"\u0938\u0947\u0935\u093e \u092a\u094d\u0930\u0926\u093e\u0924\u093e"},
gKB(){return"\u092a\u0942\u0930\u093e \u0938\u092e\u091d\u094c\u0924\u093e \u092a\u0922\u093c\u0928\u0947 \u0914\u0930 \u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0928\u0940\u091a\u0947 \u0938\u094d\u0915\u094d\u0930\u0949\u0932 \u0915\u0930\u0947\u0902\u0964"},
gKA(){return"\u0907\u0938 \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u092e\u0947\u0902 \u0915\u093e\u092e \u0915\u0940 \u0924\u093e\u0930\u0940\u0916\u0947\u0902 \u0914\u0930 \u092a\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0915\u0940 \u0938\u092e\u092f-\u0938\u0940\u092e\u093e \u0924\u092f \u0928\u0939\u0940\u0902 \u0915\u0940 \u0917\u0908 \u0939\u0948\u0902\u0964"},
gKJ(){return"\u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930\u093f\u0924 \u0938\u092e\u091d\u094c\u0924\u0947 \u0915\u094b \u092b\u093f\u0930 \u0938\u0947 \u092a\u0922\u093c\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0916\u094b\u0932\u0947\u0902\u0964"},
gKw(){return"\u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930 \u0915\u0940 \u092a\u094d\u0930\u0924\u0940\u0915\u094d\u0937\u093e"},
gKC(){return"\u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930\u093f\u0924"},
gKE(){return"\u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0935\u093e\u092a\u0938 \u0932\u093f\u092f\u093e \u0917\u092f\u093e"},
gKQ(){return"\u092c\u093e\u0926 \u092e\u0947\u0902 \u0928\u093f\u0930\u094d\u0923\u092f \u0932\u0947\u0902"},
gL1(){return"\u0905\u0928\u0941\u092c\u0902\u0927 \u0926\u0947\u0916\u0947\u0902 \u0914\u0930 \u091c\u0935\u093e\u092c \u0926\u0947\u0902"},
gKR(){return"\u0905\u0938\u094d\u0935\u0940\u0915\u093e\u0930 \u0915\u0930\u0947\u0902"},
gKr(){return"\u092e\u0948\u0902\u0928\u0947 \u0907\u0928 \u0936\u0930\u094d\u0924\u094b\u0902 \u0915\u094b \u092a\u0922\u093c \u0932\u093f\u092f\u093e \u0939\u0948 \u0914\u0930 \u0938\u0947\u0935\u093e \u092a\u094d\u0930\u0926\u093e\u0924\u093e \u0915\u0947 \u0930\u0942\u092a \u092e\u0947\u0902 \u0907\u0938 \u0938\u092e\u091d\u094c\u0924\u0947 \u0915\u0947 \u0905\u092a\u0928\u0947 \u0939\u093f\u0938\u094d\u0938\u0947 \u0915\u094b \u092a\u0942\u0930\u0940 \u0924\u0930\u0939 \u0928\u093f\u092d\u093e\u0928\u0947 \u0915\u0940 \u092a\u094d\u0930\u0924\u093f\u092c\u0926\u094d\u0927\u0924\u093e \u0915\u0930\u0924\u093e/\u0915\u0930\u0924\u0940 \u0939\u0942\u0901\u0964"},
