gLG(){return"\u0911\u0930\u094d\u0921\u0930 \u0930\u0926\u094d\u0926 \u0915\u0930 \u0926\u093f\u092f\u093e \u0917\u092f\u093e\u0964 \u0917\u094d\u0930\u093e\u0939\u0915 \u092c\u093e\u0926 \u092e\u0947\u0902 \u0905\u092a\u0928\u0940 \u091f\u093f\u092a\u094d\u092a\u0923\u0940 \u091b\u094b\u0921\u093c \u0938\u0915\u0947\u0917\u093e\u0964"},
gLD(){return"\u0911\u0930\u094d\u0921\u0930 \u0930\u0926\u094d\u0926 \u0928\u0939\u0940\u0902 \u0939\u094b \u0938\u0915\u093e\u0964 \u0909\u0938\u0915\u0940 \u0938\u094d\u0925\u093f\u0924\u093f \u091c\u093e\u0901\u091a\u0947\u0902 \u0914\u0930 \u092b\u093f\u0930 \u092a\u094d\u0930\u092f\u093e\u0938 \u0915\u0930\u0947\u0902\u0964"},
