gGa(){return"\u041f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0439 \u0434\u0438\u0430\u043b\u043e\u0433 \u0436\u0430\u043b\u043e\u0431\u044b \u0432\u0438\u0434\u0435\u043d \u0432\u0441\u0435\u043c, \u043f\u043e\u043a\u0430 \u043e\u0442\u043a\u0440\u044b\u0432\u0448\u0430\u044f \u0435\u0433\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u0430 \u043d\u0435 \u043e\u0442\u043c\u0435\u0442\u0438\u0442 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442 \u043a\u0430\u043a \u0443\u0440\u0435\u0433\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439."},
gGf(){return"\u0414\u0438\u0430\u043b\u043e\u0433 \u0436\u0430\u043b\u043e\u0431\u044b"},
gFR(){return"\u0420\u0430\u0437\u0432\u0435\u0440\u043d\u0443\u0442\u044c \u0434\u0438\u0430\u043b\u043e\u0433"},
gHn(){return"\u0423\u0434\u0430\u043b\u0438\u0442\u044c \u0430\u043a\u043a\u0430\u0443\u043d\u0442 \u043c\u043e\u0436\u043d\u043e \u0447\u0435\u0440\u0435\u0437 \u0441\u0435\u043c\u044c \u0434\u043d\u0435\u0439 \u043f\u043e\u0441\u043b\u0435 \u0437\u0430\u043a\u0440\u044b\u0442\u0438\u044f \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0435\u0433\u043e \u0437\u0430\u043a\u0430\u0437\u0430, \u0432 \u043a\u043e\u0442\u043e\u0440\u043e\u043c \u0432\u044b \u0443\u0447\u0430\u0441\u0442\u0432\u043e\u0432\u0430\u043b\u0438."},
gW8(){return"\u041f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0439 \u043f\u0440\u043e\u0444\u0438\u043b\u044c"},
gW_(){return"\u041f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0439 \u043f\u0440\u043e\u0444\u0438\u043b\u044c"},
gW1(){return"\u041e\u0431\u043d\u043e\u0432\u0438\u0442\u044c \u043f\u0440\u043e\u0444\u0438\u043b\u044c"},
