gFS(){return"\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f \u0437\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0438\u0442\u0438 \u0434\u0456\u0430\u043b\u043e\u0433 \u0441\u043a\u0430\u0440\u0433\u0438. \u0421\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0449\u0435 \u0440\u0430\u0437."},
gGh(){return"\u0426\u0435\u0439 \u0434\u0456\u0430\u043b\u043e\u0433 \u0437\u0430\u0433\u0430\u043b\u044c\u043d\u043e\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0438\u0439"},
gGg(){return"\u0410\u043a\u0442\u0438\u0432\u043d\u0443 \u0441\u043a\u0430\u0440\u0433\u0443 \u0431\u0430\u0447\u0430\u0442\u044c \u0443\u0441\u0456, \u043a\u043e\u043c\u0443 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0435 \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f. \u041f\u0438\u0448\u0456\u0442\u044c \u0432\u0432\u0456\u0447\u043b\u0438\u0432\u043e \u0439 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u043e, \u043d\u0435 \u043f\u0443\u0431\u043b\u0456\u043a\u0443\u0439\u0442\u0435 \u043e\u0441\u043e\u0431\u0438\u0441\u0442\u0456 \u0447\u0438 \u043f\u043b\u0430\u0442\u0456\u0436\u043d\u0456 \u0434\u0430\u043d\u0456. \u041d\u0435\u0432\u0438\u0440\u0456\u0448\u0435\u043d\u0430 \u0441\u043a\u0430\u0440\u0433\u0430 \u043c\u043e\u0436\u0435 \u043d\u0435\u0433\u0430\u0442\u0438\u0432\u043d\u043e \u0432\u043f\u043b\u0438\u0432\u0430\u0442\u0438 \u043d\u0430 \u0440\u0435\u0439\u0442\u0438\u043d\u0433 \u043e\u0431\u043e\u0445 \u0441\u0442\u043e\u0440\u0456\u043d."},
Go(a){return"\u041f\u043e\u043f\u0435\u0440\u0435\u0434\u043d\u044e \u0441\u043a\u0430\u0440\u0433\u0443 \u0431\u0443\u043b\u043e \u0432\u0440\u0435\u0433\u0443\u043b\u044c\u043e\u0432\u0430\u043d\u043e ("+a+"). \u0407\u0457 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f \u043f\u0440\u0438\u0445\u043e\u0432\u0430\u043d\u0456."},
gG2(){return"\u0410\u043a\u0442\u0438\u0432\u043d\u043e\u0457 \u0441\u043a\u0430\u0440\u0433\u0438 \u043d\u0435\u043c\u0430\u0454. \u041f\u043e\u043a\u0438 \u0434\u0456\u0454 \u0441\u0442\u0440\u043e\u043a \u043f\u043e\u0434\u0430\u043d\u043d\u044f, \u0457\u0457 \u043c\u043e\u0436\u0435 \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u0438 \u0431\u0443\u0434\u044c-\u044f\u043a\u0430 \u0441\u0442\u043e\u0440\u043e\u043d\u0430."},
